Gold Result:
('Robert Santana',)
*/

-- Prediction Query
SELECT player_name FROM Player_Attributes INNER JOIN Player ON Player_Attributes.player_api_id = Player.player_api_id WHERE potential = 61 ORDER BY balance DESC, Player_Attributes.id NULLS LAST, Player.id NULLS LAST LIMIT 1;

